tgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"sql","parallel":"u","leakproof":false,"signature":"_done_today(text)","definition":"0803f5ba691246529afeb4dbf67f7c93","volatility":"v","security_definer":false},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"plpgsql","parallel":"u","leakproof":false,"signature":"apply_business_change(uuid,text,text,text,text,text,date)","definition":"d0ba5d955f4357c9eb599cbce4242f3e","volatility":"v","security_definer":false},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"language":"sql","parallel":"u","leakproof":false,"signature":"crm_bundle()","definition":"b091149f61733569f2d746143373da5a","volatility":"s","security_definer":true},{"acl":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"language":"plpgsql","parallel":"u","leakproof":false,"signature":"crm_contact_move(jsonb)","definition":"e687961172aab2cfa4c8435f172f6ed5","volatility":"v","security_definer":true},{"acl":["postgres=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public"],"strict":false,"language":"plpgsql","parallel":"u","leakproof":false,"signature":"crm_contact_upsert(jsonb)","definition":"7c07f791a29bf81af2a2120caa180b72","volatility":"v","security_definer":true},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":["search_path=public"],"strict":false,"language":"plpgsql","parallel":"u","leakproof":false,"signature":"crm_opportunity_work_set(jsonb)","definition":"7fbffcf1d24354df494d91