oof":false,"signature":"require_reason(text,text)","definition":"61012d60447059c9ea79a53b4690dbf8","volatility":"i","security_definer":false},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"plpgsql","parallel":"u","leakproof":false,"signature":"set_updated_at()","definition":"c255ed84a8d9fe37ddfed5c1bb2e890b","volatility":"v","security_definer":false},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"sql","parallel":"u","leakproof":false,"signature":"stage_sla_days(text)","definition":"9bba0833e646377e9f166535acc55152","volatility":"i","security_definer":false},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"sql","parallel":"u","leakproof":false,"signature":"today_counts()","definition":"8581ff0b3bcf23246d4daa90668c9c2d","volatility":"v","security_definer":true},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"sql","parallel":"u","leakproof":false,"signature":"today_tasks(text)","definition":"3f1284bcc77d3046ef63006258ab44be","volatility":"v","security_definer":true},{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"owner":"postgres","config":null,"strict":false,"language":"sql","parallel":"u","leakproof":false,"signature":"work_items_today(text)","definition":"d0234e4b08a7dfee017ae6d44052ba21","volatility":"s","security_definer":false}],"views":[{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"name":"opportunities","owner":"postgres","options":null,"definition":" SELECT id AS opportunity_id,\n    site_id,\n    origin_inquiry_id,\n    owner_id,\n    assignee_name AS owner_name,\n    stage_code AS sales_stage_code,\n    lifecycle_status,\n    outcome,\n    amount,\n    amount_unknown_reason,\n    stage_entered_at,\n    last_activity_at,\n    last_customer_contact_at,\n    opened_at,\n    closed_at,\n    wake_up_at,\n    version,\n    brand,\n    created_at,\n    updated_at\n   FROM deals d;"},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"name":"v_assignee","owner":"postgres","options":null,"definition":" SELECT assignee_name,\n    count(*) AS total,\n    sum(\n        CASE\n            WHEN stage_group <> ''closed''::text AND stage_group IS NOT NULL THEN 1\n            ELSE 0\n        END) AS open_cnt,\n    sum(\n        CASE\n            WHEN stage_code = ''won''::text THEN 1\n            ELSE 0\n        END) AS won_cnt,\n    sum(\n        CASE\n            WHEN stage_code = ''won''::text THEN amount\n            ELSE 0::bigint\n        END) AS won_amt,\n    sum(\n        CASE\n            WHEN stage_code = ''lost''::text THEN 1\n            ELSE 0\n        END) AS lost_cnt,\n    sum(\n        CASE\n            WHEN stage_code ~~ ''badfit%''::text THEN 1\n            ELSE 0\n        END) AS badfit_cnt\n   FROM deals\n  WHERE assignee_name IS NOT NULL\n  GROUP BY assignee_name;"},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"name":"v_dup_org","owner":"postgres","options":null,"definition":" SELECT replace(replace(lower(name), '' ''::text, ''''::text), ''아파트''::text, ''''::text) AS norm,\n    count(*) AS cnt,\n    array_agg(name) AS names,\n    array_agg(id) AS ids\n   FROM organizations\n  GROUP BY (replace(replace(lower(name), '' ''::text, ''''::text), ''아파트''::text, ''''::text))\n HAVING count(*) > 1;"},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"name":"v_funnel","owner":"postgres","options":null,"definition":" SELECT brand,\n    stage_group,\n    COALESCE(stage_code, stage_raw) AS stage,\n    count(*) AS cnt,\n    sum(amount) AS amt\n   FROM deals\n  GROUP BY brand, stage_group, (COALESCE(stage_code, stage_raw));"},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"name":"v_kanban","owner":"postgres","options":null,"definition":" SELECT d.brand,\n    sc.display_group,\n    count(*) AS cnt,\n    sum(d.amount) AS amt\n   FROM deals d\n     JOIN stage_catalog sc ON sc.code = d.stage_code\n  GROUP BY d.brand, sc.display_group;"}],"triggers":[{"name":"trg_adv_upd","table":"advisory_deals","enabled":"O","definition":"CREATE TRIGGER trg_adv_upd BEFORE UPDATE ON advisory_deals FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_contacts_upd","table":"contacts","enabled":"O","definition":"CREATE TRIGGER trg_contacts_upd BEFORE UPDATE ON contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_deals_upd","table":"deals","enabled":"O","definition":"CREATE TRIGGER trg_deals_upd BEFORE UPDATE ON deals FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_inq_upd","table":"inquiries","enabled":"O","definition":"CREATE TRIGGER trg_inq_upd BEFORE UPDATE ON inquiries FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_next_actions_upd","table":"next_actions","enabled":"O","definition":"CREATE TRIGGER trg_next_actions_upd BEFORE UPDATE ON next_actions FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_organizations_upd","table":"organizations","enabled":"O","definition":"CREATE TRIGGER trg_organizations_upd BEFORE UPDATE ON organizations FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_projects_upd","table":"projects","enabled":"O","definition":"CREATE TRIGGER trg_projects_upd BEFORE UPDATE ON projects FOR EACH ROW EXECUTE FUNCTION set_updated_at()"},{"name":"trg_users_upd","table":"users","enabled":"O","definition":"CREATE TRIGGER trg_users_upd BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at()"}],"policies":[{"cmd":"ALL","qual":"true","roles":["public"],"tablename":"dashboard_state","permissive":"PERMISSIVE","policyname":"allow all","schemaname":"public","with_check":"true"},{"cmd":"SELECT","qual":"(lower(email) = lower((auth.jwt() ->> ''email''::text)))","roles":["authenticated"],"tablename":"users","permissive":"PERMISSIVE","policyname":"own row read","schemaname":"public","with_check":null}],"default_privileges":[{"acl":["postgres=rwU/postgres","anon=rwU/postgres","authenticated=rwU/postgres","service_role=rwU/postgres"],"type":"S","schema":"public","creator":"postgres"},{"acl":["postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"type":"f","schema":"public","creator":"postgres"},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"type":"r","schema":"public","creator":"postgres"},{"acl":["postgres=rwU/supabase_admin","anon=rwU/supabase_admin","authenticated=rwU/supabase_admin","service_role=rwU/supabase_admin"],"type":"S","schema":"public","creator":"supabase_admin"},{"acl":["postgres=X/supabase_admin","anon=X/supabase_admin","authenticated=X/supabase_admin","service_role=X/supabase_admin"],"type":"f","schema":"public","creator":"supabase_admin"},{"acl":["postgres=arwdDxtm/supabase_admin","anon=arwdDxtm/supabase_admin","authenticated=arwdDxtm/supabase_admin","service_role=arwdDxtm/supabase_admin"],"type":"r","schema":"public","creator":"supabase_admin"}],"custom_types":null,"custom_collations":null}'::jsonb; k text; f jsonb; original_hashes jsonb;
BEGIN
-- Read-only catalog metadata only. Never selects customer/Auth rows or Storage files.
-- Run by an authorized reviewer; this file is NOT automatically executed remotely.
WITH rel AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S')),
fun AS (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
cols AS (SELECT c.relname AS "table",a.attnum AS ordinal,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS not_null,pg_get_expr(d.adbin,d.adrelid) AS "default",a.attidentity AS identity,a.attgenerated AS generated,a.attstorage AS storage,a.attcompression AS compression,CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END AS collation,a.attacl AS acl FROM rel c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped),
snap AS (SELECT jsonb_build_object(
'version',current_setting('server_version'),'encoding',current_setting('server_encoding'),
'database',(SELECT jsonb_build_object('collate',datcollate,'ctype',datctype,'provider',datlocprovider,'locale',datlocale) FROM pg_database WHERE datname=current_database()),
'schema',(SELECT jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',nspacl) FROM pg_namespace WHERE nspname='public'),
'relations',(SELECT jsonb_agg(jsonb_build_object('name',relname,'kind',relkind,'owner',pg_get_userbyid(relowner),'acl',relacl,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'options',reloptions,'persistence',relpersistence,'replica_identity',relreplident,'tablespace',reltablespace) ORDER BY relname) FROM rel),
'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY "table",ordinal) FROM cols a),
'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred) ORDER BY c.relname,k.conname) FROM rel c JOIN pg_constraint k ON k.conrelid=c.oid),
'indexes',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'clustered',i.indisclustered,'replica_identity',i.indisreplident,'constraint_owned',EXISTS(SELECT 1 FROM pg_constraint k WHERE k.conindid=i.indexrelid AND k.conrelid=c.oid AND k.contype IN ('p','u','x'))) ORDER BY c.relname,ic.relname) FROM rel c JOIN pg_index i ON i.indrelid=c.oid JOIN pg_class ic ON ic.oid=i.indexrelid),
'sequences',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'type',format_type(s.seqtypid,NULL),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle,'owned_by',(SELECT format('%I.%I.%I',n.nspname,t.relname,a.attname) FROM pg_depend d JOIN pg_class t ON t.oid=d.refobjid JOIN pg_namespace n ON n.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=d.refobjsubid WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.refclassid='pg_class'::regclass AND d.deptype IN ('a','i') LIMIT 1)) ORDER BY c.relname) FROM rel c JOIN pg_sequence s ON s.seqrelid=c.oid),
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',md5(replace(replace(pg_get_functiondef(p.oid),chr(13)||chr(10),chr(10)),chr(13),chr(10))),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'security_definer',p.prosecdef,'config',p.proconfig,'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'volatility',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'leakproof',p.proleakproof) ORDER BY p.oid::regprocedure::text) FROM fun p WHERE p.prokind IN ('f','p')),
'views',(SELECT jsonb_agg(jsonb_build_object('name',relname,'definition',pg_get_viewdef(oid,true),'options',reloptions,'owner',pg_get_userbyid(relowner),'acl',relacl) ORDER BY relname) FROM rel WHERE relkind='v'),
'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) ORDER BY c.relname,t.tgname) FROM rel c JOIN pg_trigger t ON t.tgrelid=c.oid WHERE NOT t.tgisinternal),
'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='public'),
'default_privileges',(SELECT jsonb_agg(jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl) ORDER BY pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclnamespace=0 OR n.nspname='public'),
'creators',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'can_login',r.rolcanlogin,'superuser',r.rolsuper,'bypass_rls',r.rolbypassrls,'inherit',r.rolinherit,'can_create_public',has_schema_privilege(r.oid,'public','CREATE'),'executor_member',pg_has_role(current_user,r.oid,'MEMBER')) ORDER BY r.rolname) FROM pg_roles r WHERE has_schema_privilege(r.oid,'public','CREATE') OR EXISTS(SELECT 1 FROM fun p WHERE p.proowner=r.oid) OR EXISTS(SELECT 1 FROM pg_default_acl d WHERE d.defaclrole=r.oid AND (d.defaclnamespace=0 OR d.defaclnamespace='public'::regnamespace))),
'extensions',(SELECT jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'owner',pg_get_userbyid(e.extowner)) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
'custom_types',(SELECT jsonb_agg(jsonb_build_object('name',t.typname,'kind',t.typtype,'base',format_type(t.typbasetype,t.typtypmod))) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype IN ('e','d')),
'custom_collations',(SELECT jsonb_agg(jsonb_build_object('name',c.collname,'provider',c.collprovider,'collate',c.collcollate,'ctype',c.collctype,'locale',c.colllocale,'version',c.collversion)) FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace WHERE n.nspname='public'),
'dependencies',(SELECT jsonb_agg(jsonb_build_object('source',pg_describe_object(d.classid,d.objid,d.objsubid),'target',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid),'type',d.deptype) ORDER BY d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid) FROM pg_depend d WHERE (d.classid='pg_proc'::regclass AND d.objid IN(SELECT oid FROM fun)) OR (d.classid='pg_rewrite'::regclass AND d.objid IN(SELECT rw.oid FROM pg_rewrite rw JOIN rel c ON c.oid=rw.ev_class)) OR (d.classid='pg_class'::regclass AND d.objid IN(SELECT oid FROM rel)) OR (d.classid='pg_attrdef'::regclass AND d.objid IN(SELECT a.oid FROM pg_attrdef a JOIN rel c ON c.oid=a.adrelid)))
) AS payload) SELECT payload INTO actual FROM snap;

SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'raw_md5',md5(pg_get_functiondef(p.oid)),'canonical_md5',md5(replace(replace(pg_get_functiondef(p.oid),chr(13)||chr(10),chr(10)),chr(13),chr(10)))) ORDER BY p.oid::regprocedure::text)
 INTO original_hashes FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prokind IN ('f','p');
RAISE NOTICE 'baseline rollback raw/canonical function hashes: %',original_hashes;
FOREACH k IN ARRAY ARRAY['schema','relations','columns','constraints','indexes','sequences','functions','views','triggers','policies','default_privileges','custom_types','custom_collations'] LOOP
 IF NOT ((actual->k) @> (expected->k) AND (expected->k) @> (actual->k)) THEN
  RAISE EXCEPTION 'Baseline drift in %, refuse rollback',k;
 END IF;
END LOOP;
-- jsonb containment treats arrays as sets; explicitly preserve exact config order too.
FOR f IN SELECT value FROM jsonb_array_elements(actual->'functions') LOOP
 IF (f->'config') IS DISTINCT FROM (SELECT e->'config' FROM jsonb_array_elements(expected->'functions') e WHERE e->>'signature'=f->>'signature') THEN
  RAISE EXCEPTION 'Baseline drift in function config, refuse rollback';
 END IF;
END LOOP;
