FOREACH k IN ARRAY ARRAY['schema','default_privileges'] LOOP
 IF NOT ((actual->k) @> (expected->k) AND (expected->k) @> (actual->k)) THEN RAISE EXCEPTION 'Before metadata mismatch: %',k; END IF;
END LOOP;
